fn ladder(ks: std::ops::RangeInclusive<u32>, f: impl Fn(f64) -> f64) -> Vec<f64> {
    let e: Vec<f64> = ks.map(|k| f(0.5f64.powi(k as i32))).collect();
    e.windows(2).filter(|p| p[1] > 1e-12).map(|p| (p[0] / p[1]).log2()).collect()
}

#[test]
fn forcing_fixed_outer_rtol_error_is_bounded_by_tolerance_floor() {
    for rtol in [1e-4, 1e-6] {
        let atol = 1e-2 * rtol; // independent of h, as in the adaptive driver
        for k in 3..=8 {
            let h = 0.5f64.powi(k);
            let direct = fixed_endpoint_wrms(Arm::Direct, h, atol, rtol);
            let forced = fixed_endpoint_wrms(Arm::Forcing, h, atol, rtol);
            assert!(forced <= (3.0 * direct).max(1.0), "rtol={rtol} h={h} {forced} vs {direct}");
        }
    }
}

#[test]
fn direct_fixed_step_stiff_pr_order_is_reduced_band() {
    let s = ladder(2..=6, |h| pr_direct_error(-1e4, 0.0, h));
    assert!(s.len() >= 3 && s.iter().all(|o| (2.7..=3.6).contains(o)), "{s:?}");
}

